public static class Solution
{
    public static int CountVowels(string s)
    {
        int count = 0;
        foreach (char c in s)
        {
            switch (char.ToLowerInvariant(c))
            {
                case 'a':
                case 'e':
                case 'i':
                case 'o':
                case 'u':
                    count++;
                    break;
            }
        }
        return count;
    }
}

