    public static Dictionary<char, int> CountCharacters(string s)
    {
        Dictionary<char, int> counts = new Dictionary<char, int>();
        foreach (char c in s)
        {
            if (counts.TryGetValue(c, out int count))
            {
                counts[c] = count + 1;
            }
            else
            {
                counts[c] = 1;
            }
        }
        return counts;
    }
}

