public static class Solution
{
    public static string RemoveDuplicateChars(string s)
    {
        HashSet<char> seen = new HashSet<char>();
        char[] result = new char[s.Length];
        int index = 0;
        foreach (char c in s)
        {
            if (seen.Add(c))
            {
                result[index++] = c;
            }
        }
        return new string(result, 0, index);
    }
}

