{
    public static int AgeOn(Person person, DateOnly date)
    {
        int age = date.Year - person.BirthDate.Year;
        if (person.BirthDate > date.AddYears(-age))
        {
            age--;
        }
        return age;
    }

    public static List<Person> BornBefore(IEnumerable<Person> people, DateOnly date)
    {
        return people.Where(p => p.BirthDate < date).ToList();
    }
}

