public record Product(string Sku, string Name, decimal Price);
public record OrderLine(string Sku, int Quantity);

public static class Solution
{
    public static Dictionary<string, Product> IndexBySku(IEnumerable<Product> products)
    {
        var result = new Dictionary<string, Product>(StringComparer.OrdinalIgnoreCase);
        foreach (var product in products)
        {
            result[product.Sku] = product;
        }
        return result;
    }

    public static decimal TotalForOrder(IEnumerable<OrderLine> lines, IReadOnlyDictionary<string, Product> products)
    {
        decimal total = 0m;
        foreach (var line in lines)
        {
            if (products.TryGetValue(line.Sku, out var product) && product is not null)
            {
                total += product.Price * line.Quantity;
            }
        }
        return total;
    }
}

