public static class Solution
{
    public static int CountPrimes(int n)
    {
        if (n < 2) return 0;
        bool[] isComposite = new bool[n + 1];
        int count = 0;
        for (int i = 2; i <= n; i++)
        {
            if (!isComposite[i])
            {
                count++;
                if ((long)i * i <= n)
                {
                    for (int j = i * i; j <= n; j += i)
                    {
                        isComposite[j] = true;
                    }
                }
            }
        }
        return count;
    }
}

