public static class Solution
{
    public static List<int> PrimeFactors(int n)
    {
        var factors = new List<int>();
        if (n < 2) return factors;
        for (int divisor = 2; (long)divisor * divisor <= n; divisor++)
        {
            while (n % divisor == 0)
            {
                factors.Add(divisor);
                n /= divisor;
            }
        }
        if (n > 1) factors.Add(n);
        return factors;
    }
}

