public static class Solution
{
    public static int CountPrimes(int limit)
    {
        if (limit < 2) return 0;
        bool[] composite = new bool[limit + 1];
        int count = 0;
        for (int i = 2; i <= limit; i++)
        {
            if (!composite[i])
            {
                count++;
                if ((long)i * i <= limit)
                {
                    for (int j = i * i; j <= limit; j += i)
                    {
                        composite[j] = true;
                    }
                }
            }
        }
        return count;
    }
}

