    {
        Dictionary<string, List<int>> groups = new Dictionary<string, List<int>>();
        groups["even"] = new List<int>();
        groups["odd"] = new List<int>();
        foreach (int number in numbers)
        {
            if (number % 2 == 0)
            {
                groups["even"].Add(number);
            }
            else
