public static class Solution
{
    public static Dictionary<string, string> ParseKeyValues(string s)
    {
        var dict = new Dictionary<string, string>();
        if (string.IsNullOrWhiteSpace(s)) return dict;
        string[] pairs = s.Split(';');
        foreach (string pair in pairs)
        {
            string trimmed = pair.Trim();
            if (trimmed.Length == 0) continue;
            string[] kv = trimmed.Split('=');
            if (kv.Length != 2) throw new FormatException("Invalid pair: " + pair);
            string key = kv[0].Trim();
            string value = kv[1].Trim();
            if (key.Length == 0) throw new FormatException("Empty key");
            if (dict.ContainsKey(key)) throw new FormatException("Duplicate key: " + key);
            dict[key] = value;
        }
        return dict;
    }
}

