public sealed record Point(int X, int Y);

public static class Solution
{
    public static Point? ParsePoint(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return null;
        }

        var s = text.Trim();
        if (s.Length < 5 || s[0] != '(' || s[^1] != ')')
        {
            return null;
        }

        var inner = s[1..^1];
        var parts = inner.Split(',');
        if (parts.Length != 2)
        {
            return null;
        }

        if (!int.TryParse(parts[0].Trim(), out var x))
        {
            return null;
        }

        if (!int.TryParse(parts[1].Trim(), out var y))
        {
            return null;
        }

        return new Point(x, y);
    }
}

tests:
public static class Tests
{
    [KiteTest("parses points")]
    public static void TestPoints()
    {
        expect(Solution.ParsePoint("(1,2)") is { X: 1, Y: 2 }, "basic");
        expect(Solution.ParsePoint(" ( -3 , 4 ) ") is { X: -3, Y: 4 }, "spaces negative");
        expect(Solution.ParsePoint("(1,2,3)") == null, "too many");
        expect(Solution.ParsePoint("abc") == null, "invalid");
    }
}

