public sealed record Sale(string Product, int Quantity, decimal UnitPrice);

public static class Solution
{
    public static List<Sale> ParseSales(string? text)
    {
        var result = new List<Sale>();
        if (string.IsNullOrWhiteSpace(text))
        {
            return result;
        }

        foreach (var rawLine in text.Split('\n'))
        {
            var line = rawLine.Trim();
            if (line.Length == 0)
            {
                continue;
            }

            var parts = line.Split(':');
            if (parts.Length != 3)
            {
                continue;
            }

            var product = parts[0].Trim();
            if (product.Length == 0)
            {
                continue;
            }

            if (!int.TryParse(parts[1].Trim(), out var quantity))
            {
                continue;
            }

            if (!decimal.TryParse(parts[2].Trim(), System.Globalization.NumberStyles.Number, System.Globalization.CultureInfo.InvariantCulture, out var price))
            {
                continue;
            }

            result.Add(new Sale(product, quantity, price));
        }

        return result;
    }
}

tests:
public static class Tests
{
    [KiteTest("parses sales")]
    public static void TestSales()
    {
        expect(Solution.ParseSales("apple:2:1.50").Count == 1, "count");
        expect(Solution.ParseSales("apple:2:1.50")[0].UnitPrice == 1.50m, "price");
        expect(Solution.ParseSales("bad\nbanana:3:2.25").Single().Product == "banana", "skips bad");
        expect(Solution.ParseSales("x:0:0").Single().Quantity == 0, "zero");
    }
}

