public static class Solution
{
    public static double[] ParseDoubles(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return Array.Empty<double>();
        }

        var values = new List<double>();
        foreach (var part in text.Split(new[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries))
        {
            if (double.TryParse(part, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var value))
            {
                values.Add(value);
            }
        }

        return values.ToArray();
    }
}

tests:
public static class Tests
{
    [KiteTest("parses doubles")]
    public static void TestDoubles()
    {
        var a = Solution.ParseDoubles("1.5 -2.25 3");
        expect(a.Length == 3, "count");
        expect(Math.Abs(a[0] - 1.5) < 0.0001, "first");
        expect(Math.Abs(a[1] + 2.25) < 0.0001, "negative");
        expect(Solution.ParseDoubles("").Length == 0, "empty");
    }
}

