public sealed record Person(string Name, int Age, bool IsActive);

public static class Solution
{
    public static Person? ParsePerson(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return null;
        }

        var parts = text.Split(',');
        if (parts.Length != 3)
        {
            return null;
        }

        var name = parts[0].Trim();
        if (name.Length == 0)
        {
            return null;
        }

        if (!int.TryParse(parts[1].Trim(), out var age))
        {
            return null;
        }

        if (!bool.TryParse(parts[2].Trim(), out var isActive))
        {
            return null;
        }

        return new Person(name, age, isActive);
    }
}

tests:
public static class Tests
{
    [KiteTest("parses person")]
