    {
        expect(Solution.ParsePerson("Alice,30,true") is { Name: "Alice", Age: 30, IsActive: true }, "basic");
        expect(Solution.ParsePerson(" Bob , 0 , False ") is { Name: "Bob", Age: 0, IsActive: false }, "trim/case");
        expect(Solution.ParsePerson("Alice,30") == null, "missing");
        expect(Solution.ParsePerson("Alice,x,true") == null, "bad age");
    }
}

