public sealed record Color(byte Red, byte Green, byte Blue);

public static class Solution
{
    public static Color? ParseHexColor(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return null;
        }

        var s = text.Trim();
        if (s.Length != 7 || s[0] != '#')
        {
            return null;
        }

        if (!byte.TryParse(s.Substring(1, 2), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture, out var red))
        {
            return null;
        }

        if (!byte.TryParse(s.Substring(3, 2), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture, out var green))
        {
            return null;
        }

        if (!byte.TryParse(s.Substring(5, 2), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture, out var blue))
        {
            return null;
        }

        return new Color(red, green, blue);
    }
}

tests:
public static class Tests
{
    [KiteTest("parses hex color")]
    public static void TestColor()
    {
        expect(Solution.ParseHexColor("#336699") is { Red: 0x33, Green: 0x66, Blue: 0x99 }, "basic");
        expect(Solution.ParseHexColor(" #abcdef ") is { Red: 0xab, Green: 0xcd, Blue: 0xef }, "lowercase trim");
        expect(Solution.ParseHexColor("#12345") == null, "length");
        expect(Solution.ParseHexColor("#12GG34") == null, "invalid hex");
    }
}
